/* MultiCalc — Chemistry texts: per element [description, name origin] in el / en / es, plus the uses vocabulary.
   Written for this app (own wording); facts cross-checked against standard references. */
var MC_ELTEXT={
1:{el:["Το ελαφρύτερο και πιο άφθονο στοιχείο του σύμπαντος, βασικό συστατικό των άστρων. Στη Γη βρίσκεται κυρίως στο νερό και στις οργανικές ενώσεις.","Από τα ελληνικά ὕδωρ + γένος: «αυτό που γεννά νερό» (όνομα του Lavoisier)."],en:["The lightest and most abundant element in the universe, the main ingredient of stars. On Earth it occurs mostly in water and organic compounds.","From Greek hydro + genes, 'water-forming' (a name coined by Lavoisier)."],es:["El elemento más ligero y abundante del universo, ingrediente principal de las estrellas. En la Tierra se encuentra sobre todo en el agua y en compuestos orgánicos.","Del griego hydro + genes, «generador de agua» (nombre acuñado por Lavoisier)."]},
2:{el:["Άχρωμο, αδρανές ευγενές αέριο, το δεύτερο πιο άφθονο στοιχείο του σύμπαντος. Εντοπίστηκε πρώτα στο φάσμα του Ήλιου, και σε κανονική πίεση δεν στερεοποιείται ούτε στο απόλυτο μηδέν.","Από το ελληνικό ἥλιος, «ήλιος», επειδή εντοπίστηκε πρώτα στο φως του Ήλιου."],en:["A colorless, inert noble gas, the second most abundant element in the universe. It was detected in the Sun's spectrum before it was found on Earth, and at normal pressure it does not solidify even at absolute zero.","From Greek helios, 'sun', because it was first seen in sunlight."],es:["Gas noble incoloro e inerte, el segundo elemento más abundante del universo. Se detectó en el espectro del Sol antes que en la Tierra y, a presión normal, no se solidifica ni en el cero absoluto.","Del griego helios, «sol», porque se observó primero en la luz solar."]},
3:{el:["Το ελαφρύτερο μέταλλο και το λιγότερο πυκνό στερεό στοιχείο, τόσο μαλακό που κόβεται με μαχαίρι. Τροφοδοτεί επαναφορτιζόμενες μπαταρίες και χρησιμοποιείται σε ορισμένα ψυχιατρικά φάρμακα.","Από το ελληνικό λίθος, επειδή βρέθηκε σε ορυκτό και όχι στη στάχτη φυτών."],en:["The lightest metal and the least dense solid element, so soft it can be cut with a knife. It powers rechargeable batteries and is used in some psychiatric medicines.","From Greek lithos, 'stone', because it was found in a mineral rather than in plant ash."],es:["El metal más ligero y el elemento sólido menos denso, tan blando que se corta con un cuchillo. Alimenta baterías recargables y se usa en algunos medicamentos psiquiátricos.","Del griego lithos, «piedra», porque se halló en un mineral y no en cenizas vegetales."]},
4:{el:["Ελαφρύ, άκαμπτο μέταλλο με χρώμα ατσαλιού, διαφανές στις ακτίνες Χ. Οι ενώσεις του είναι πολύ τοξικές· χρησιμοποιείται σε κράματα για την αεροδιαστημική και σε καθρέφτες τηλεσκοπίων.","Από το ελληνικό βήρυλλος, ο πολύτιμος λίθος στον οποίο βρέθηκε."],en:["A light, stiff, steel-gray metal that is transparent to X-rays. Its compounds are highly toxic; it is used in aerospace alloys and in telescope mirrors.","From Greek beryllos, the gemstone beryl in which it was found."],es:["Metal ligero, rígido y de color gris acero, transparente a los rayos X. Sus compuestos son muy tóxicos; se usa en aleaciones aeroespaciales y en espejos de telescopios.","Del griego beryllos, la gema berilo en la que se encontró."]},
5:{el:["Σκληρό, εύθραυστο ημιμέταλλο που σπάνια βρίσκεται ελεύθερο· εξορύσσεται ως βορικά ορυκτά, όπως ο βόρακας. Ενισχύει το ανθεκτικό στη θερμότητα γυαλί και είναι ιχνοστοιχείο για τα φυτά.","Από τα αραβικά buraq και τα περσικά burah, ονομασίες του βόρακα."],en:["A hard, brittle metalloid that rarely occurs free in nature; it is mined as borate minerals such as borax. It strengthens heat-resistant glass and is a micronutrient for plants.","From Arabic buraq and Persian burah, names for borax."],es:["Metaloide duro y quebradizo que casi nunca aparece libre en la naturaleza; se extrae como boratos, como el bórax. Refuerza el vidrio resistente al calor y es un micronutriente para las plantas.","Del árabe buraq y el persa burah, nombres del bórax."]},
6:{el:["Η ραχοκοκαλιά της οργανικής χημείας και κάθε γνωστής μορφής ζωής. Εμφανίζεται ως διαμάντι, γραφίτης, φουλερένια και γραφένιο, με πολύ διαφορετική σκληρότητα και αγωγιμότητα.","Από το λατινικό carbo, «κάρβουνο, ξυλάνθρακας»."],en:["The backbone of organic chemistry and of all known life. It occurs as diamond, graphite, fullerenes and graphene, which differ enormously in hardness and conductivity.","From Latin carbo, 'coal, charcoal'."],es:["Base de la química orgánica y de toda la vida conocida. Se presenta como diamante, grafito, fullerenos y grafeno, con durezas y conductividades muy distintas.","Del latín carbo, «carbón, carbón vegetal»."]},
7:{el:["Άχρωμο, άοσμο αέριο που αποτελεί περίπου το 78% της ατμόσφαιρας. Είναι απαραίτητο για τις πρωτεΐνες και το DNA, και η βιομηχανική δέσμευσή του παράγει λιπάσματα.","Από τα ελληνικά νίτρον + γένος: «που γεννά νίτρο». Στα γαλλικά λέγεται azote, «άζωος»."],en:["A colorless, odorless gas that makes up about 78% of the atmosphere. It is essential for proteins and DNA, and industrial fixation turns it into fertilizers.","From Greek nitron + genes, 'nitre-forming'; in French it is azote, 'lifeless'."],es:["Gas incoloro e inodoro que forma cerca del 78 % de la atmósfera. Es esencial para proteínas y ADN, y su fijación industrial produce fertilizantes.","Del griego nitron + genes, «generador de nitro»; en francés azote, «sin vida»."]},
8:{el:["Δραστικό αέριο που αποτελεί περίπου το 21% της ατμόσφαιρας και, σε ενώσεις, σχεδόν το μισό της μάζας του φλοιού της Γης. Η αερόβια ζωή εξαρτάται από αυτό και συντηρεί κάθε καύση.","Από τα ελληνικά ὀξύς + γένος: «που γεννά οξέα» (Lavoisier, που πίστευε λανθασμένα ότι όλα τα οξέα το περιέχουν)."],en:["A reactive gas that makes up about 21% of the atmosphere and, in compounds, nearly half of the Earth's crust by mass. Aerobic life depends on it, and it sustains all combustion.","From Greek oxys + genes, 'acid-forming' (Lavoisier, who wrongly believed all acids contain it)."],es:["Gas reactivo que forma cerca del 21 % de la atmósfera y, en compuestos, casi la mitad de la masa de la corteza terrestre. La vida aerobia depende de él y mantiene toda combustión.","Del griego oxys + genes, «generador de ácidos» (Lavoisier, que creía erróneamente que todos los ácidos lo contienen)."]},
9:{el:["Το πιο ηλεκτραρνητικό και δραστικό στοιχείο, που ενώνεται με σχεδόν κάθε άλλο. Οι ενώσεις του βρίσκονται στο αντικολλητικό PTFE, στα φθοριούχα των οδοντόκρεμων και στον εμπλουτισμό ουρανίου.","Από το λατινικό fluere, «ρέω», επειδή ο φθορίτης χρησιμοποιούνταν ως ρευστοποιητής."],en:["The most electronegative and reactive element, combining with almost every other one. Its compounds appear in non-stick PTFE, in the fluoride of toothpaste and in uranium enrichment.","From Latin fluere, 'to flow', because fluorspar was used as a flux."],es:["El elemento más electronegativo y reactivo, que se combina con casi todos los demás. Sus compuestos están en el PTFE antiadherente, el flúor de las pastas dentales y el enriquecimiento de uranio.","Del latín fluere, «fluir», porque la fluorita se usaba como fundente."]},
10:{el:["Άχρωμο, αδρανές ευγενές αέριο που λάμπει κοκκινοπορτοκαλί σε σωλήνες εκκένωσης, τις κλασικές επιγραφές «νέον». Είναι σπάνιο στην ατμόσφαιρα και χρησιμοποιείται και ως κρυογονικό ψυκτικό.","Από το ελληνικό νέος."],en:["A colorless, inert noble gas that glows reddish-orange in discharge tubes, the classic 'neon sign'. It is rare in the atmosphere and is also used as a cryogenic coolant.","From Greek neos, 'new'."],es:["Gas noble incoloro e inerte que brilla de rojo anaranjado en tubos de descarga, los clásicos letreros de neón. Es raro en la atmósfera y también se usa como refrigerante criogénico.","Del griego neos, «nuevo»."]},
11:{el:["Μαλακό, αργυρόλευκο μέταλλο που αντιδρά έντονα με το νερό. Το χλωριούχο νάτριο είναι το μαγειρικό αλάτι, και τα ιόντα νατρίου είναι ζωτικά για τα νευρικά σήματα και την ισορροπία των υγρών.","Από το αγγλικό soda· το σύμβολο Na προέρχεται από το λατινικό natrium, από το αραβικό natrun."],en:["A soft, silvery metal that reacts violently with water. Sodium chloride is table salt, and sodium ions are vital for nerve signals and fluid balance.","From English 'soda'; the symbol Na comes from Latin natrium, from Arabic natrun."],es:["Metal blando y plateado que reacciona violentamente con el agua. El cloruro de sodio es la sal común, y los iones de sodio son vitales para los impulsos nerviosos y el equilibrio de líquidos.","Del inglés soda; el símbolo Na viene del latín natrium, del árabe natrun."]},
12:{el:["Ελαφρύ, αργυρόλευκο μέταλλο που καίγεται με εκτυφλωτική λευκή φλόγα. Βρίσκεται στο κέντρο της χλωροφύλλης και χρησιμοποιείται σε ελαφριά κράματα για αεροσκάφη και οχήματα.","Από τη Μαγνησία, περιοχή της Θεσσαλίας, όπου βρέθηκαν ορυκτά του."],en:["A light, silvery metal that burns with a dazzling white flame. It sits at the heart of chlorophyll and is used in lightweight alloys for aircraft and vehicles.","After Magnesia, a district of Thessaly in Greece where magnesium minerals were found."],es:["Metal ligero y plateado que arde con una llama blanca deslumbrante. Está en el centro de la clorofila y se usa en aleaciones ligeras para aviones y vehículos.","De Magnesia, región de Tesalia, en Grecia, donde se hallaron sus minerales."]},
13:{el:["Το πιο άφθονο μέταλλο στον φλοιό της Γης, ελαφρύ, ανθεκτικό στη διάβρωση και εξαιρετικός αγωγός. Ήταν πολυτελές μέταλλο μέχρι που η ηλεκτρολυτική μέθοδος των Hall και Héroult (1886) το έκανε φθηνό.","Από το λατινικό alumen, «στύψη»· το όνομα επινόησε ο Humphry Davy."],en:["The most abundant metal in the Earth's crust, light, corrosion-resistant and an excellent conductor. It was a luxury metal until the Hall–Héroult electrolytic process (1886) made it cheap.","From Latin alumen, 'alum'; the name was coined by Humphry Davy."],es:["El metal más abundante de la corteza terrestre, ligero, resistente a la corrosión y excelente conductor. Fue un metal de lujo hasta que el proceso electrolítico de Hall y Héroult (1886) lo abarató.","Del latín alumen, «alumbre»; el nombre lo ideó Humphry Davy."]},
14:{el:["Ημιμέταλλο, το δεύτερο πιο άφθονο στοιχείο στον φλοιό της Γης, κυρίως ως άμμος και χαλαζίας. Το υπερκαθαρό πυρίτιο είναι η βάση των τσιπ υπολογιστών και των ηλιακών κυττάρων.","Από το λατινικό silex, «πυρίτης λίθος»."],en:["A metalloid and the second most abundant element in the Earth's crust, mostly as sand and quartz. Ultra-pure silicon is the foundation of computer chips and solar cells.","From Latin silex, 'flint'."],es:["Metaloide, el segundo elemento más abundante de la corteza terrestre, sobre todo como arena y cuarzo. El silicio ultrapuro es la base de los chips y las células solares.","Del latín silex, «pedernal»."]},
15:{el:["Δραστικό αμέταλλο με λευκή, κόκκινη και μαύρη αλλοτροπική μορφή. Είναι απαραίτητο στο DNA, στο ATP και στα οστά, ενώ τα φωσφορικά άλατα είναι βασικά στα λιπάσματα.","Από το ελληνικό φωσφόρος, «φωτοφόρος», επειδή ο λευκός φώσφορος λάμπει στο σκοτάδι."],en:["A reactive nonmetal with white, red and black allotropes. It is essential in DNA, ATP and bones, and phosphates are central to fertilizers.","From Greek phosphoros, 'light-bringer', because white phosphorus glows in the dark."],es:["No metal reactivo con alótropos blanco, rojo y negro. Es esencial en el ADN, el ATP y los huesos, y los fosfatos son clave en los fertilizantes.","Del griego phosphoros, «portador de luz», porque el fósforo blanco brilla en la oscuridad."]},
16:{el:["Έντονα κίτρινο αμέταλλο γνωστό από την αρχαιότητα, που βρίσκεται κοντά σε ηφαίστεια και σε θειούχα ορυκτά. Το θειικό οξύ που παράγεται από αυτό είναι από τις πιο διαδεδομένες βιομηχανικές χημικές ουσίες.","Από το λατινικό sulfur (αβέβαιης προέλευσης)· στα αρχαία ελληνικά θεῖον, απ' όπου το «θείο»."],en:["A bright yellow nonmetal known since antiquity, found near volcanoes and in sulfide minerals. The sulfuric acid made from it is one of the most widely produced industrial chemicals.","From Latin sulfur (of uncertain origin); in Greek it was theion."],es:["No metal amarillo brillante conocido desde la antigüedad, presente cerca de volcanes y en minerales sulfurados. El ácido sulfúrico que se obtiene de él es uno de los productos químicos industriales más producidos.","Del latín sulfur (origen incierto); en griego, theion."]},
17:{el:["Κιτρινοπράσινο αέριο με έντονη οσμή και ισχυρό απολυμαντικό. Χρησιμοποιείται στην επεξεργασία πόσιμου νερού και στο πλαστικό PVC· στο αλάτι ενώνεται με το νάτριο.","Από το ελληνικό χλωρός, «ανοιχτό πράσινο»."],en:["A greenish-yellow, pungent gas and a powerful disinfectant. It treats drinking water and is a building block of PVC plastic; in table salt it is combined with sodium.","From Greek chloros, 'pale green'."],es:["Gas amarillo verdoso de olor penetrante y potente desinfectante. Se usa para potabilizar el agua y en el plástico PVC; en la sal común está unido al sodio.","Del griego chloros, «verde pálido»."]},
18:{el:["Το τρίτο πιο άφθονο αέριο της ατμόσφαιρας (περίπου 0,9%), εντελώς αδρανές. Προστατεύει τις συγκολλήσεις και γεμίζει λαμπτήρες πυράκτωσης.","Από το ελληνικό ἀργός, «οκνηρός», επειδή δεν αντιδρά."],en:["The third most abundant gas in the atmosphere (about 0.9%), completely inert. It shields welds from air and fills incandescent bulbs.","From Greek argos, 'idle' or 'lazy', because it does not react."],es:["El tercer gas más abundante de la atmósfera (cerca del 0,9 %), totalmente inerte. Protege las soldaduras del aire y llena las bombillas incandescentes.","Del griego argos, «perezoso», porque no reacciona."]},
19:{el:["Μαλακό αλκαλικό μέταλλο που αντιδρά έντονα με το νερό. Τα ιόντα καλίου είναι κρίσιμα για τα νεύρα και τους μύες, και το στοιχείο είναι βασικό λίπασμα για τις καλλιέργειες.","Από το αγγλικό potash· το σύμβολο K προέρχεται από το λατινικό kalium, από το αραβικό al-qali."],en:["A soft alkali metal that reacts vigorously with water. Potassium ions are crucial for nerves and muscles, and the element is a key crop fertilizer.","From English 'potash'; the symbol K comes from Latin kalium, from Arabic al-qali."],es:["Metal alcalino blando que reacciona con violencia con el agua. Los iones de potasio son cruciales para nervios y músculos, y el elemento es un fertilizante clave para los cultivos.","Del inglés potash; el símbolo K viene del latín kalium, del árabe al-qali."]},
20:{el:["Δραστικό αλκαλικό γαιώδες μέταλλο και το πιο άφθονο μέταλλο στο ανθρώπινο σώμα, κυρίως στα οστά και στα δόντια. Ο ασβεστόλιθος, η κιμωλία και το τσιμέντο είναι ενώσεις ασβεστίου.","Από το λατινικό calx, «ασβέστης»."],en:["A reactive alkaline earth metal and the most abundant metal in the human body, mainly in bones and teeth. Limestone, chalk and cement are all calcium compounds.","From Latin calx, 'lime'."],es:["Metal alcalinotérreo reactivo y el metal más abundante del cuerpo humano, sobre todo en huesos y dientes. La caliza, la tiza y el cemento son compuestos de calcio.","Del latín calx, «cal»."]},
21:{el:["Ασημόλευκο μεταβατικό μέταλλο που ο Mendeleev είχε προβλέψει ως «εκα-βόριο» πριν βρεθεί το 1879. Μικρές προσθήκες ενισχύουν τα κράματα αλουμινίου για την αεροδιαστημική και τον αθλητικό εξοπλισμό.","Από το λατινικό Scandia, «Σκανδιναβία», όπου βρέθηκαν τα ορυκτά του."],en:["A silvery transition metal that Mendeleev had predicted as 'eka-boron' before it was found in 1879. Small additions strengthen aluminium alloys for aerospace and sports equipment.","From Latin Scandia, 'Scandinavia', where its minerals were found."],es:["Metal de transición plateado que Mendeléyev había predicho como «eka-boro» antes de su hallazgo en 1879. Pequeñas adiciones refuerzan las aleaciones de aluminio para la industria aeroespacial y el equipamiento deportivo.","Del latín Scandia, «Escandinavia», donde se hallaron sus minerales."]},
22:{el:["Ισχυρό, ελαφρύ και ανθεκτικό στη διάβρωση μέταλλο με εξαιρετική αναλογία αντοχής προς βάρος. Χρησιμοποιείται σε αεροσκάφη και ιατρικά εμφυτεύματα, ενώ το διοξείδιο του τιτανίου είναι βασική λευκή χρωστική.","Από τους Τιτάνες της ελληνικής μυθολογίας (όνομα του Klaproth)."],en:["A strong, light, corrosion-resistant metal with an outstanding strength-to-weight ratio. It is used in aircraft and medical implants, and titanium dioxide is a key white pigment.","After the Titans of Greek mythology (named by Klaproth)."],es:["Metal resistente, ligero y resistente a la corrosión, con una relación resistencia-peso sobresaliente. Se usa en aviones e implantes médicos, y el dióxido de titanio es un pigmento blanco fundamental.","De los Titanes de la mitología griega (nombre dado por Klaproth)."]},
23:{el:["Σκληρό, όλκιμο μέταλλο που κυρίως ενισχύει τους χάλυβες για εργαλεία και ελατήρια. Χρησιμοποιείται και σε μεγάλες μπαταρίες ροής βαναδίου.","Από τη Vanadis, άλλο όνομα της σκανδιναβικής θεάς Freyja, επειδή οι ενώσεις του έχουν ζωηρά χρώματα."],en:["A hard, ductile metal that mainly strengthens steel for tools and springs. It also serves in large vanadium redox flow batteries.","After Vanadis, another name of the Norse goddess Freyja, because its compounds are brightly colored."],es:["Metal duro y dúctil que sobre todo refuerza los aceros para herramientas y muelles. También se usa en grandes baterías de flujo de vanadio.","De Vanadis, otro nombre de la diosa nórdica Freyja, porque sus compuestos tienen colores vivos."]},
24:{el:["Σκληρό, γυαλιστερό μέταλλο που δεν αμαυρώνεται. Δίνει στον ανοξείδωτο χάλυβα την αντοχή του στη διάβρωση και στο χρωμίωμα την καθρεπτώδη λάμψη.","Από το ελληνικό χρῶμα, επειδή οι ενώσεις του έχουν έντονα χρώματα."],en:["A hard, shiny metal that resists tarnish. It gives stainless steel its corrosion resistance and chrome plating its mirror finish.","From Greek chroma, 'color', because its compounds are vividly colored."],es:["Metal duro y brillante que resiste el deslustre. Da al acero inoxidable su resistencia a la corrosión y al cromado su acabado de espejo.","Del griego chroma, «color», porque sus compuestos son de colores vivos."]},
25:{el:["Σκληρό, εύθραυστο μέταλλο απαραίτητο στην παραγωγή χάλυβα. Χρησιμοποιείται και σε αλκαλικές μπαταρίες, ενώ ίχνη του είναι ζωτικά για τους οργανισμούς.","Από το μεσαιωνικό λατινικό magnesia, όνομα που δινόταν στον πυρολουσίτη και σε συναφή ορυκτά."],en:["A hard, brittle metal that is indispensable in steelmaking. It also appears in alkaline batteries, and trace amounts are essential to living things.","From medieval Latin magnesia, a name used for pyrolusite and related minerals."],es:["Metal duro y quebradizo, indispensable en la fabricación del acero. También se usa en pilas alcalinas, y trazas de él son esenciales para los seres vivos.","Del latín medieval magnesia, nombre que se daba a la pirolusita y minerales afines."]},
26:{el:["Η ραχοκοκαλιά της σύγχρονης βιομηχανίας, κυρίως ως χάλυβας. Είναι το βασικό συστατικό του πυρήνα της Γης και βρίσκεται στο κέντρο της αιμοσφαιρίνης, που μεταφέρει οξυγόνο στο αίμα.","Από το παλαιοαγγλικό iron· το σύμβολο Fe προέρχεται από το λατινικό ferrum."],en:["The backbone of modern industry, mostly used as steel. It is the main component of the Earth's core and sits at the heart of hemoglobin, which carries oxygen in blood.","From Old English iron; the symbol Fe comes from Latin ferrum."],es:["La columna vertebral de la industria moderna, sobre todo como acero. Es el componente principal del núcleo terrestre y está en el centro de la hemoglobina, que transporta el oxígeno en la sangre.","Del inglés antiguo iron; el símbolo Fe viene del latín ferrum."]},
27:{el:["Σκληρό, γυαλιστερό, μαγνητικό μέταλλο. Είναι ζωτικό για τις καθόδους μπαταριών ιόντων λιθίου, για υπερκράματα και για τη βιταμίνη B12, ενώ οι ενώσεις του δίνουν το βαθύ «μπλε του κοβαλτίου».","Από το γερμανικό Kobold, «ξωτικό», που οι μεταλλωρύχοι κατηγορούσαν για τα δύσκολα και τοξικά μεταλλεύματα."],en:["A hard, lustrous, magnetic metal. It is vital to lithium-ion battery cathodes, superalloys and vitamin B12, and its compounds give the deep 'cobalt blue'.","From German Kobold, 'goblin', which miners blamed for troublesome and toxic ores."],es:["Metal duro, brillante y magnético. Es vital para los cátodos de las baterías de iones de litio, las superaleaciones y la vitamina B12, y sus compuestos dan el profundo «azul cobalto».","Del alemán Kobold, «duende», al que los mineros culpaban por menas problemáticas y tóxicas."]},
28:{el:["Αργυρόλευκο, ανθεκτικό στη διάβρωση, μαγνητικό μέταλλο. Είναι βασικό συστατικό του ανοξείδωτου χάλυβα, των κερμάτων και των επαναφορτιζόμενων μπαταριών.","Από το γερμανικό Kupfernickel, «χαλκός του διαβόλου», ένα μετάλλευμα που έμοιαζε με χαλκό αλλά δεν απέδιδε."],en:["A silvery, corrosion-resistant, magnetic metal. It is a major ingredient of stainless steel, coins and rechargeable batteries.","From German Kupfernickel, 'devil's copper', an ore that looked like copper but yielded none."],es:["Metal plateado, resistente a la corrosión y magnético. Es ingrediente principal del acero inoxidable, las monedas y las baterías recargables.","Del alemán Kupfernickel, «cobre del diablo», una mena que parecía cobre pero no lo daba."]},
29:{el:["Κοκκινωπό μέταλλο και ένας από τους καλύτερους αγωγούς του ηλεκτρισμού, γνωστό και κατεργασμένο από την προϊστορία. Γίνονται από αυτό καλώδια, σωλήνες και κράματα όπως ο μπρούντζος και ο ορείχαλκος.","Από το λατινικό cuprum, από την Κύπρο, το νησί που ήταν σημαντική πηγή του."],en:["A reddish metal and one of the best electrical conductors, worked since prehistory. It makes wires and pipes, and alloys such as bronze and brass.","From Latin cuprum, after Cyprus, the island that was once a major source."],es:["Metal rojizo y uno de los mejores conductores eléctricos, trabajado desde la prehistoria. Se usa en cables y tuberías, y en aleaciones como el bronce y el latón.","Del latín cuprum, por Chipre, la isla que fue una fuente importante."]},
30:{el:["Γαλαζόλευκο μέταλλο που επικαλύπτει τον χάλυβα (γαλβανισμός) για να μην σκουριάζει. Με τον χαλκό σχηματίζει τον ορείχαλκο, και ο ψευδάργυρος είναι απαραίτητος σε εκατοντάδες ένζυμα του σώματος.","Από το γερμανικό Zink, αβέβαιης προέλευσης."],en:["A bluish-white metal that coats steel as galvanizing to prevent rust. Alloyed with copper it makes brass, and zinc is essential to hundreds of enzymes in the body.","From German Zink, of uncertain origin."],es:["Metal blanquiazulado que recubre el acero (galvanizado) para evitar la oxidación. Aleado con cobre forma el latón, y el zinc es esencial para cientos de enzimas del cuerpo.","Del alemán Zink, de origen incierto."]},
31:{el:["Μαλακό μέταλλο που λιώνει στο χέρι (29,8 °C) αλλά παραμένει υγρό σε εξαιρετικά μεγάλο εύρος θερμοκρασιών. Το αρσενικούχο και το νιτρίδιο του γαλλίου είναι βασικά για LED, λέιζερ και γρήγορα ηλεκτρονικά.","Από το λατινικό Gallia, «Γαλλία», πατρίδα του ανακαλυπτή του."],en:["A soft metal that melts in the hand (29.8 °C) yet stays liquid over an extraordinary temperature range. Gallium arsenide and gallium nitride are key to LEDs, lasers and fast electronics.","From Latin Gallia, 'France', the homeland of its discoverer."],es:["Metal blando que se funde en la mano (29,8 °C) pero permanece líquido en un rango de temperaturas extraordinario. El arseniuro y el nitruro de galio son clave en LED, láseres y electrónica rápida.","Del latín Gallia, «Francia», patria de su descubridor."]},
32:{el:["Εύθραυστο, γυαλιστερό ημιμέταλλο που ο Mendeleev είχε προβλέψει ως «εκα-πυρίτιο». Χρησιμοποιήθηκε στα πρώτα τρανζίστορ και παραμένει πολύτιμο στις οπτικές ίνες και στους φακούς υπερύθρων.","Από το λατινικό Germania, «Γερμανία», πατρίδα του ανακαλυπτή του."],en:["A brittle, shiny metalloid that Mendeleev had predicted as 'eka-silicon'. It was used in the first transistors and is still valued in fiber optics and infrared lenses.","From Latin Germania, 'Germany', the homeland of its discoverer."],es:["Metaloide frágil y brillante que Mendeléyev había predicho como «eka-silicio». Se usó en los primeros transistores y aún se valora en fibra óptica y lentes infrarrojas.","Del latín Germania, «Alemania», patria de su descubridor."]},
33:{el:["Ημιμέταλλο γνωστό για την τοξικότητά του, κάποτε αγαπημένο δηλητήριο. Σήμερα χρησιμοποιείται κυρίως ως πρόσμιξη σε ημιαγωγούς, όπως το αρσενικούχο γάλλιο.","Από το ελληνικό ἀρσενικόν, το κίτρινο ορυκτό ορπιμέντο (θειούχο αρσενικό)."],en:["A metalloid infamous for its toxicity, once a favorite poison. Today it is mainly used as a dopant in semiconductors such as gallium arsenide.","From Greek arsenikon, the yellow mineral orpiment (arsenic sulfide)."],es:["Metaloide famoso por su toxicidad, antaño un veneno predilecto. Hoy se usa sobre todo como dopante en semiconductores como el arseniuro de galio.","Del griego arsenikon, el mineral amarillo oropimente (sulfuro de arsénico)."]},
34:{el:["Αμέταλλο του οποίου η ηλεκτρική αγωγιμότητα αυξάνεται με το φως, γι' αυτό χρησιμοποιήθηκε σε φωτοκύτταρα και φωτοαντιγραφικά. Είναι απαραίτητο ιχνοστοιχείο, αλλά τοξικό σε περίσσεια.","Από το ελληνικό σελήνη, ως «σύντροφος» του τελλουρίου, που πήρε το όνομά του από τη Γη."],en:["A nonmetal whose electrical conductivity rises in light, once used in photocells and photocopiers. It is an essential trace nutrient, but toxic in excess.","From Greek selene, 'Moon', a companion to tellurium, which is named after the Earth."],es:["No metal cuya conductividad eléctrica aumenta con la luz, usado antaño en fotocélulas y fotocopiadoras. Es un oligoelemento esencial, pero tóxico en exceso.","Del griego selene, «Luna», compañera del telurio, que lleva el nombre de la Tierra."]},
35:{el:["Ένα από τα δύο μόνο στοιχεία που είναι υγρά σε θερμοκρασία δωματίου (μαζί με τον υδράργυρο): σκούρο κοκκινοκαφέ υγρό με έντονη οσμή. Χρησιμοποιείται σε επιβραδυντικά φλόγας και στη χημική σύνθεση.","Από το ελληνικό βρῶμος, «δυσωδία»."],en:["One of only two elements that are liquid at room temperature (with mercury): a dark red-brown, pungent liquid. It is used in flame retardants and chemical synthesis.","From Greek bromos, 'stench'."],es:["Uno de los dos únicos elementos líquidos a temperatura ambiente (junto con el mercurio): un líquido pardo rojizo oscuro de olor penetrante. Se usa en retardantes de llama y en síntesis química.","Del griego bromos, «hedor»."]},
36:{el:["Άχρωμο, αδρανές ευγενές αέριο. Μια φασματική γραμμή του κρυπτού όρισε το μέτρο από το 1960 έως το 1983, και το αέριο γεμίζει ορισμένους λαμπτήρες υψηλών επιδόσεων.","Από το ελληνικό κρυπτός, «κρυμμένος»."],en:["A colorless, inert noble gas. A krypton spectral line defined the metre from 1960 to 1983, and the gas fills some high-performance lamps.","From Greek kryptos, 'hidden'."],es:["Gas noble incoloro e inerte. Una línea espectral del criptón definió el metro entre 1960 y 1983, y el gas llena algunas lámparas de alto rendimiento.","Del griego kryptos, «oculto»."]},
37:{el:["Πολύ μαλακό, ιδιαίτερα δραστικό αλκαλικό μέταλλο που αναφλέγεται στον αέρα. Τα άτομά του χρησιμοποιούνται σε ατομικά ρολόγια και στη μελέτη υπερψυχρής ύλης.","Από το λατινικό rubidus, «βαθύ κόκκινο», λόγω των κόκκινων φασματικών γραμμών του."],en:["A very soft, highly reactive alkali metal that ignites in air. Its atoms are used in atomic clocks and in studies of ultracold matter.","From Latin rubidus, 'deep red', after its red spectral lines."],es:["Metal alcalino muy blando y altamente reactivo que se inflama en el aire. Sus átomos se usan en relojes atómicos y en el estudio de la materia ultrafría.","Del latín rubidus, «rojo intenso», por sus líneas espectrales rojas."]},
38:{el:["Μαλακό αλκαλικό γαιώδες μέταλλο που καίγεται με βαθύ κόκκινο χρώμα, δίνοντας το κόκκινο στα πυροτεχνήματα και στις φωτοβολίδες. Ο φερρίτης του στροντίου χρησιμεύει σε μόνιμους μαγνήτες.","Από το Strontian, χωριό της Σκωτίας όπου βρέθηκε το πρώτο ορυκτό."],en:["A soft alkaline earth metal that burns crimson, giving fireworks and flares their red. Strontium ferrite is used in permanent magnets.","After Strontian, a village in Scotland where the first mineral was found."],es:["Metal alcalinotérreo blando que arde con color carmesí, el rojo de los fuegos artificiales y las bengalas. La ferrita de estroncio se usa en imanes permanentes.","De Strontian, pueblo de Escocia donde se halló el primer mineral."]},
39:{el:["Αργυρόλευκο μέταλλο που βρίσκεται μαζί με τις σπάνιες γαίες. Οι ενώσεις του δίνουν κόκκινους φωσφόρους σε οθόνες και LED, και ο γρανάτης υττρίου-αλουμινίου (YAG) είναι βασικός κρύσταλλος λέιζερ.","Από το Ytterby, χωριό κοντά στη Στοκχόλμη όπου βρέθηκε το ορυκτό του."],en:["A silvery metal found with the rare earths. Its compounds give red phosphors in screens and LEDs, and yttrium aluminium garnet (YAG) is a key laser crystal.","After Ytterby, the Swedish village near Stockholm where its mineral was found."],es:["Metal plateado que aparece junto a las tierras raras. Sus compuestos dan fósforos rojos en pantallas y LED, y el granate de itrio y aluminio (YAG) es un cristal láser clave.","De Ytterby, la aldea sueca cercana a Estocolmo donde se halló su mineral."]},
40:{el:["Ισχυρό μέταλλο, ανθεκτικό στη διάβρωση, που σχεδόν δεν απορροφά νετρόνια· γι' αυτό επενδύει τις ράβδους πυρηνικού καυσίμου. Το οξείδιό του σχηματίζει το συνθετικό πετράδι κυβικό ζιρκόνιο.","Από το περσικό zargun, «χρυσόχρωμο», για το πετράδι ζιρκόν."],en:["A strong, corrosion-resistant metal that barely absorbs neutrons, which is why it clads nuclear fuel rods. Its oxide forms the synthetic gemstone cubic zirconia.","From Persian zargun, 'gold-colored', for the gem zircon."],es:["Metal resistente a la corrosión que apenas absorbe neutrones, por lo que reviste las barras de combustible nuclear. Su óxido forma la gema sintética circonita cúbica.","Del persa zargun, «color de oro», por la gema circón."]},
41:{el:["Μαλακό, όλκιμο μέταλλο που γίνεται υπεραγωγός σε χαμηλές θερμοκρασίες. Ενισχύει χάλυβες υψηλής αντοχής και χρησιμοποιείται στους υπεραγώγιμους μαγνήτες των μαγνητικών τομογράφων.","Από τη Νιόβη, κόρη του Ταντάλου στη μυθολογία, επειδή μοιάζει πολύ με το ταντάλιο."],en:["A soft, ductile metal that becomes superconducting at low temperatures. It strengthens high-strength steels and is used in the superconducting magnets of MRI scanners.","After Niobe, daughter of Tantalus in Greek myth, because it so closely resembles tantalum."],es:["Metal blando y dúctil que se vuelve superconductor a bajas temperaturas. Refuerza aceros de alta resistencia y se usa en los imanes superconductores de los escáneres de resonancia magnética.","De Níobe, hija de Tántalo en la mitología griega, porque se parece mucho al tántalo."]},
42:{el:["Μέταλλο με πολύ υψηλό σημείο τήξης που κρατά τον χάλυβα ισχυρό σε ακραίες θερμοκρασίες. Είναι απαραίτητο ιχνοστοιχείο σε ένζυμα, μεταξύ αυτών και σε ορισμένα που δεσμεύουν άζωτο.","Από το ελληνικό μόλυβδος, επειδή τα μεταλλεύματά του έμοιαζαν με του μολύβδου."],en:["A metal with a very high melting point that keeps steel strong at extreme temperatures. It is an essential trace element in enzymes, including some that fix nitrogen.","From Greek molybdos, 'lead', because its ores resembled lead ores."],es:["Metal de punto de fusión muy alto que mantiene resistente al acero a temperaturas extremas. Es un oligoelemento esencial en enzimas, entre ellas algunas que fijan nitrógeno.","Del griego molybdos, «plomo», porque sus menas se parecían a las del plomo."]},
43:{el:["Το ελαφρύτερο στοιχείο χωρίς σταθερά ισότοπα και το πρώτο που παρήχθη τεχνητά. Το ισότοπο τεχνήτιο-99m είναι ο πιο διαδεδομένος ραδιενεργός ιχνηθέτης στην ιατρική απεικόνιση.","Από το ελληνικό τεχνητός."],en:["The lightest element with no stable isotopes and the first one made artificially. Its isotope technetium-99m is the most widely used radioactive tracer in medical imaging.","From Greek technetos, 'artificial'."],es:["El elemento más ligero sin isótopos estables y el primero obtenido artificialmente. Su isótopo tecnecio-99m es el trazador radiactivo más usado en imagen médica.","Del griego technetos, «artificial»."]},
44:{el:["Σκληρό, αργυρόλευκο μέταλλο της ομάδας του λευκόχρυσου, ανθεκτικό στη φθορά και τη διάβρωση. Σκληραίνει κράματα λευκόχρυσου και παλλαδίου και χρησιμοποιείται σε ηλεκτρονικά και καταλύτες.","Από το λατινικό Ruthenia, το λατινικό όνομα της Ρωσίας."],en:["A hard, silvery platinum-group metal that resists wear and corrosion. It hardens platinum and palladium alloys and is used in electronics and catalysis.","From Latin Ruthenia, the Latin name for Russia."],es:["Metal duro y plateado del grupo del platino, resistente al desgaste y la corrosión. Endurece las aleaciones de platino y paladio y se usa en electrónica y catálisis.","Del latín Ruthenia, nombre latino de Rusia."]},
45:{el:["Σπάνιο, αργυρόλευκο και πολύ ανακλαστικό μέταλλο της ομάδας του λευκόχρυσου. Είναι καίριο στους καταλυτικούς μετατροπείς των αυτοκινήτων, και τα κοσμήματα συχνά επιστρώνονται με ρόδιο.","Από το ελληνικό ῥόδον, «τριαντάφυλλο», λόγω του ροδόχρου χρώματος των αλάτων του."],en:["A rare, silvery-white, highly reflective platinum-group metal. It is crucial in car catalytic converters, and jewelry is often rhodium-plated.","From Greek rhodon, 'rose', after the rose-red color of its salts."],es:["Metal raro, blanco plateado y muy reflectante, del grupo del platino. Es crucial en los catalizadores de los coches, y la joyería suele chaparse con rodio.","Del griego rhodon, «rosa», por el color rosado de sus sales."]},
46:{el:["Αργυρόλευκο μέταλλο της ομάδας του λευκόχρυσου που απορροφά υδρογόνο έως και περίπου 900 φορές τον όγκο του. Είναι σημαντικός καταλύτης στα αυτοκίνητα και χρησιμοποιείται σε ηλεκτρονικά και κοσμήματα.","Από τον αστεροειδή Παλλάδα, που ανακαλύφθηκε το 1802."],en:["A silvery platinum-group metal that can absorb up to about 900 times its own volume of hydrogen. It is a major catalyst in cars and is used in electronics and jewelry.","After the asteroid Pallas, discovered in 1802."],es:["Metal plateado del grupo del platino que puede absorber hasta unas 900 veces su volumen de hidrógeno. Es un catalizador importante en los coches y se usa en electrónica y joyería.","Del asteroide Palas, descubierto en 1802."]},
47:{el:["Ο καλύτερος αγωγός του ηλεκτρισμού και της θερμότητας ανάμεσα στα μέταλλα, και πολύ ανακλαστικός. Χρησιμοποιείται από την αρχαιότητα σε νομίσματα, κοσμήματα και μαχαιροπίρουνα, και είναι ζωτικός στα ηλεκτρονικά και στα φωτοβολταϊκά.","Από το παλαιοαγγλικό siolfor· το σύμβολο Ag προέρχεται από το λατινικό argentum, «λαμπερό»."],en:["The best electrical and thermal conductor of all metals, and highly reflective. Used since antiquity for coins, jewelry and cutlery, it is vital in electronics and solar panels.","From Old English siolfor; the symbol Ag comes from Latin argentum, 'shining'."],es:["El mejor conductor eléctrico y térmico de todos los metales, y muy reflectante. Usada desde la antigüedad en monedas, joyas y cubertería, es vital en electrónica y paneles solares.","Del inglés antiguo siolfor; el símbolo Ag viene del latín argentum, «brillante»."]},
48:{el:["Μαλακό, γαλαζόλευκο μέταλλο, τοξικό και συσσωρεύεται στον οργανισμό. Έχει χρησιμοποιηθεί σε επαναφορτιζόμενες μπαταρίες νικελίου-καδμίου και σε έντονες κίτρινες και κόκκινες χρωστικές.","Από το λατινικό cadmia, όνομα της καλαμίνης (μεταλλεύματος ψευδαργύρου), στην οποία βρέθηκε."],en:["A soft, bluish-white metal that is toxic and accumulates in the body. It has been used in rechargeable nickel–cadmium batteries and in vivid yellow and red pigments.","From Latin cadmia, a name for calamine (a zinc ore), in which it was found."],es:["Metal blando y blanquiazulado, tóxico y que se acumula en el organismo. Se ha usado en baterías recargables de níquel-cadmio y en pigmentos amarillos y rojos intensos.","Del latín cadmia, nombre de la calamina (mena de zinc), en la que se halló."]},
49:{el:["Πολύ μαλακό, αργυρόλευκο μέταλλο. Το οξείδιο ινδίου-κασσίτερου σχηματίζει το διαφανές αγώγιμο στρώμα στις οθόνες αφής και στις επίπεδες οθόνες.","Από το λατινικό indicum, «λουλακί», λόγω της έντονης λουλακί φασματικής γραμμής του."],en:["A very soft, silvery metal. Indium tin oxide forms the transparent conductive layer in touchscreens and flat displays.","From Latin indicum, 'indigo', after its bright indigo-blue spectral line."],es:["Metal muy blando y plateado. El óxido de indio y estaño forma la capa conductora transparente de las pantallas táctiles y planas.","Del latín indicum, «índigo», por su brillante línea espectral azul índigo."]},
50:{el:["Μαλακό, αργυρόλευκο μέταλλο γνωστό από την Εποχή του Χαλκού, όταν κραματοποιούνταν με χαλκό. Επικαλύπτει τα μεταλλικά κουτιά, παράγει κόλληση και προστατεύει από τη διάβρωση.","Από το παλαιοαγγλικό tin· το σύμβολο Sn προέρχεται από το λατινικό stannum."],en:["A soft, silvery metal known since the Bronze Age, when it was alloyed with copper. It coats steel cans, makes solder and protects against corrosion.","From Old English tin; the symbol Sn comes from Latin stannum."],es:["Metal blando y plateado conocido desde la Edad del Bronce, cuando se aleaba con cobre. Recubre las latas de acero, forma soldaduras y protege de la corrosión.","Del inglés antiguo tin; el símbolo Sn viene del latín stannum."]},
51:{el:["Εύθραυστο, αργυρόλευκο ημιμέταλλο γνωστό από την αρχαιότητα. Σκληραίνει κράματα μολύβδου, βελτιώνει επιβραδυντικά φλόγας και χρησιμοποιείται σε ορισμένους ημιαγωγούς.","Αβέβαιης προέλευσης· συχνά εξηγείται ως το ελληνικό ἀντί-μόνος, «όχι μόνο». Το σύμβολο Sb προέρχεται από το λατινικό stibium."],en:["A brittle, silvery metalloid known since antiquity. It hardens lead alloys, improves flame retardants and appears in some semiconductors.","Of uncertain origin, often explained as Greek anti-monos, 'not alone'; the symbol Sb comes from Latin stibium."],es:["Metaloide frágil y plateado conocido desde la antigüedad. Endurece las aleaciones de plomo, mejora los retardantes de llama y aparece en algunos semiconductores.","De origen incierto, a menudo explicado como el griego anti-monos, «no solo»; el símbolo Sb viene del latín stibium."]},
52:{el:["Εύθραυστο ημιμέταλλο, από τα σπανιότερα σταθερά στοιχεία του φλοιού της Γης. Το τελλουρίδιο του καδμίου είναι κορυφαίο υλικό για φωτοβολταϊκά λεπτής μεμβράνης, και το τελλούριο βελτιώνει την κατεργασιμότητα του χάλυβα και του χαλκού.","Από το λατινικό tellus, «Γη»."],en:["A brittle metalloid, among the rarest stable elements in the Earth's crust. Cadmium telluride is a leading thin-film solar cell material, and tellurium improves the machinability of steel and copper.","From Latin tellus, 'Earth'."],es:["Metaloide frágil, uno de los elementos estables más raros de la corteza terrestre. El telururo de cadmio es un material líder en células solares de capa fina, y el telurio mejora la maquinabilidad del acero y el cobre.","Del latín tellus, «Tierra»."]},
53:{el:["Γυαλιστερό σκούρο στερεό που εξαχνώνεται σε ιώδεις ατμούς. Είναι απαραίτητο για τις ορμόνες του θυρεοειδούς και χρησιμοποιείται ως αντισηπτικό και σε σκιαγραφικά.","Από το ελληνικό ἰώδης, «ιώδης», λόγω του χρώματος των ατμών του."],en:["A lustrous dark solid that sublimes into purple vapor. It is essential for thyroid hormones and is used as an antiseptic and in imaging contrast agents.","From Greek iodes, 'violet', after the color of its vapor."],es:["Sólido oscuro y brillante que sublima en vapores violeta. Es esencial para las hormonas tiroideas y se usa como antiséptico y en medios de contraste para imagen.","Del griego iodes, «violeta», por el color de su vapor."]},
54:{el:["Βαρύ, άχρωμο ευγενές αέριο, το πρώτο που αποδείχθηκε ότι σχηματίζει ενώσεις. Φωτίζει λαμπερά λευκό στους λαμπτήρες και τροφοδοτεί ιοντικούς προωθητές διαστημοπλοίων.","Από το ελληνικό ξένος, «ξένος»."],en:["A heavy, colorless noble gas, the first to be shown to form compounds. It glows bright white in lamps and powers ion thrusters on spacecraft.","From Greek xenos, 'stranger'."],es:["Gas noble pesado e incoloro, el primero que se demostró que forma compuestos. Brilla con luz blanca intensa en lámparas y propulsa los motores iónicos de naves espaciales.","Del griego xenos, «extraño»."]},
55:{el:["Χρυσαφί, μαλακό μέταλλο που λιώνει λίγο πάνω από τη θερμοκρασία δωματίου. Οι ταλαντώσεις των ατόμων καισίου-133 ορίζουν το δευτερόλεπτο στο Διεθνές Σύστημα Μονάδων.","Από το λατινικό caesius, «γαλάζιος του ουρανού», λόγω των μπλε φασματικών γραμμών του."],en:["A soft, golden-tinged metal that melts just above room temperature. The vibrations of cesium-133 atoms define the second in the International System of Units.","From Latin caesius, 'sky-blue', after its blue spectral lines."],es:["Metal blando de tono dorado que se funde justo por encima de la temperatura ambiente. Las vibraciones de los átomos de cesio-133 definen el segundo en el Sistema Internacional de Unidades.","Del latín caesius, «azul celeste», por sus líneas espectrales azules."]},
56:{el:["Μαλακό, αργυρόλευκο αλκαλικό γαιώδες μέταλλο που οξειδώνεται γρήγορα στον αέρα. Το θειικό βάριο χρησιμοποιείται ως «γεύμα βαρίου» στην ακτινολογική απεικόνιση του πεπτικού, και ενώσεις του χρωματίζουν πράσινα τα πυροτεχνήματα.","Από το ελληνικό βαρύς, λόγω του πυκνού ορυκτού βαρύτη."],en:["A soft, silvery alkaline earth metal that oxidizes rapidly in air. Barium sulfate serves as the 'barium meal' for X-ray imaging of the digestive tract, and barium compounds color fireworks green.","From Greek barys, 'heavy', after the dense mineral baryte."],es:["Metal alcalinotérreo blando y plateado que se oxida rápidamente en el aire. El sulfato de bario sirve como «papilla de bario» en la radiografía del tubo digestivo, y sus compuestos tiñen de verde los fuegos artificiales.","Del griego barys, «pesado», por el denso mineral baritina."]},
57:{el:["Μαλακό, αργυρόλευκο μέταλλο των σπάνιων γαιών που δίνει το όνομά του στη σειρά των λανθανιδών. Χρησιμοποιείται σε μπαταρίες νικελίου-υδριδίου μετάλλου, φακούς φωτογραφικών μηχανών και καταλύτες.","Από το ελληνικό λανθάνειν, «κρύβομαι»."],en:["A soft, silvery rare-earth metal that gives its name to the lanthanide series. It is used in nickel–metal hydride batteries, camera lenses and catalysts.","From Greek lanthanein, 'to lie hidden'."],es:["Metal blando y plateado de las tierras raras que da nombre a la serie de los lantánidos. Se usa en baterías de níquel-hidruro metálico, objetivos de cámara y catalizadores.","Del griego lanthanein, «estar oculto»."]},
58:{el:["Το πιο άφθονο στοιχείο των σπάνιων γαιών, περίπου τόσο κοινό στον φλοιό όσο ο χαλκός. Το οξείδιό του στιλβώνει το γυαλί και δουλεύει σε καταλυτικούς μετατροπείς, και τα κράματά του με σίδηρο δίνουν σπίθα στους αναπτήρες.","Από τον νάνο πλανήτη Δήμητρα (Ceres), που ανακαλύφθηκε το 1801."],en:["The most abundant rare-earth element, about as common in the crust as copper. Its oxide polishes glass and works in catalytic converters, and cerium–iron alloys give the spark in lighter flints.","After the dwarf planet Ceres, discovered in 1801."],es:["El elemento de las tierras raras más abundante, tan común en la corteza como el cobre. Su óxido pule el vidrio y actúa en catalizadores, y las aleaciones de cerio y hierro dan la chispa de las piedras de encendedor.","Del planeta enano Ceres, descubierto en 1801."]},
59:{el:["Μαλακό, αργυρόλευκο μέταλλο των σπάνιων γαιών με πράσινα άλατα. Ενισχύει κράματα μαγνησίου, δίνει κιτρινοπράσινο χρώμα σε γυαλί και κεραμικά και χρησιμοποιείται σε μαγνήτες.","Από το ελληνικό πράσιος + δίδυμος: «πράσινο δίδυμο», επειδή διαχωρίστηκε από το «διδύμιο»."],en:["A soft, silvery rare-earth metal with green salts. It strengthens magnesium alloys, gives glass and ceramics yellow-green colors and is used in magnets.","From Greek prasios + didymos, 'green twin', because it was separated from 'didymium'."],es:["Metal blando y plateado de las tierras raras, de sales verdes. Refuerza las aleaciones de magnesio, da colores amarillo verdosos al vidrio y la cerámica y se usa en imanes.","Del griego prasios + didymos, «gemelo verde», porque se separó del «didimio»."]},
60:{el:["Αργυρό στοιχείο των σπάνιων γαιών, γνωστό για τους μαγνήτες νεοδυμίου, τους ισχυρότερους εμπορικούς μόνιμους μαγνήτες, που βρίσκονται σε ανεμογεννήτριες, ακουστικά και ηλεκτροκινητήρες.","Από το ελληνικό νέος + δίδυμος: «νέο δίδυμο»."],en:["A silvery rare-earth metal best known for neodymium magnets, the strongest commercial permanent magnets, found in wind turbines, headphones and electric motors.","From Greek neos + didymos, 'new twin'."],es:["Metal plateado de las tierras raras, conocido por los imanes de neodimio, los imanes permanentes comerciales más potentes, presentes en aerogeneradores, auriculares y motores eléctricos.","Del griego neos + didymos, «nuevo gemelo»."]},
61:{el:["Ραδιενεργό στοιχείο των σπάνιων γαιών χωρίς σταθερά ισότοπα, που σχηματίζεται σε ελάχιστα ίχνη στα μεταλλεύματα ουρανίου. Το προμήθιο-147 έχει χρησιμοποιηθεί σε φωτεινές βαφές και σε πυρηνικές μπαταρίες μεγάλης διάρκειας.","Από τον Προμηθέα, τον Τιτάνα που έκλεψε τη φωτιά από τους θεούς."],en:["A radioactive rare earth with no stable isotopes, formed in tiny traces in uranium ores. Promethium-147 has been used in luminous paint and long-life nuclear batteries.","After Prometheus, the Titan who stole fire from the gods."],es:["Tierra rara radiactiva sin isótopos estables, que se forma en trazas diminutas en las menas de uranio. El prometio-147 se ha usado en pinturas luminosas y baterías nucleares de larga duración.","De Prometeo, el titán que robó el fuego a los dioses."]},
62:{el:["Αργυρό στοιχείο των σπάνιων γαιών που χρησιμοποιείται στους μαγνήτες σαμαρίου-κοβαλτίου, οι οποίοι διατηρούν τη δύναμή τους σε υψηλές θερμοκρασίες. Το σαμάριο-153 χρησιμοποιείται για την ανακούφιση του πόνου από οστικές μεταστάσεις.","Από το ορυκτό σαμαρσκίτη, που πήρε το όνομα του Ρώσου μεταλλειολόγου Βασίλι Σαμάρσκι-Μπιχοβέτς."],en:["A silvery rare earth used in samarium–cobalt magnets, which keep their strength at high temperatures. Samarium-153 is used to relieve pain from bone metastases.","From the mineral samarskite, named after the Russian mining official Vasili Samarsky-Bykhovets."],es:["Tierra rara plateada usada en imanes de samario-cobalto, que conservan su fuerza a altas temperaturas. El samario-153 se emplea para aliviar el dolor de las metástasis óseas.","Del mineral samarskita, nombrado por el funcionario minero ruso Vasili Samarski-Bykhovets."]},
63:{el:["Η πιο δραστική από τις σπάνιες γαίες, με κόκκινους και μπλε φωσφόρους σε οθόνες και λαμπτήρες. Τα τραπεζογραμμάτια του ευρώ χρησιμοποιούν ενώσεις ευρωπίου σε φθορίζοντα χαρακτηριστικά ασφαλείας.","Από την Ευρώπη."],en:["The most reactive rare earth, with red and blue phosphors in screens and lamps. Euro banknotes use europium compounds in their fluorescent security features.","After Europe."],es:["La tierra rara más reactiva, con fósforos rojos y azules en pantallas y lámparas. Los billetes de euro usan compuestos de europio en sus elementos fluorescentes de seguridad.","De Europa."]},
64:{el:["Αργυρό στοιχείο των σπάνιων γαιών με ισχυρό παραμαγνητισμό και τεράστια ικανότητα σύλληψης νετρονίων. Οι ενώσεις του χρησιμοποιούνται ως σκιαγραφικά στους μαγνητικούς τομογράφους.","Από το ορυκτό γαδολινίτη, που πήρε το όνομα του χημικού Johan Gadolin."],en:["A silvery rare earth with strong paramagnetism and an enormous ability to capture neutrons. Its compounds are used as contrast agents in MRI scans.","After the mineral gadolinite, named for the chemist Johan Gadolin."],es:["Tierra rara plateada con fuerte paramagnetismo y una enorme capacidad de captura de neutrones. Sus compuestos se usan como medios de contraste en resonancias magnéticas.","Del mineral gadolinita, nombrado por el químico Johan Gadolin."]},
65:{el:["Μαλακό, αργυρό στοιχείο των σπάνιων γαιών, του οποίου οι ενώσεις φθορίζουν έντονα πράσινες. Χρησιμοποιείται σε πράσινους φωσφόρους για φωτισμό και οθόνες, και σε ορισμένα μαγνητικά κράματα.","Από το Ytterby, χωριό κοντά στη Στοκχόλμη."],en:["A soft, silvery rare earth whose compounds fluoresce bright green. It is used in green phosphors for lighting and screens, and in some magnetic alloys.","After Ytterby, the Swedish village near Stockholm."],es:["Tierra rara blanda y plateada cuyos compuestos fluorescen en verde intenso. Se usa en fósforos verdes para iluminación y pantallas, y en algunas aleaciones magnéticas.","De Ytterby, la aldea sueca cercana a Estocolmo."]},
66:{el:["Αργυρό στοιχείο των σπάνιων γαιών με αξιοσημείωτες μαγνητικές ιδιότητες. Ενισχύει τους μαγνήτες νεοδυμίου σε υψηλές θερμοκρασίες και υπάρχει σε γεννήτριες ανεμογεννητριών και ηλεκτρικά οχήματα.","Από το ελληνικό δυσπρόσιτος, «δύσκολο να το φτάσεις»."],en:["A silvery rare earth with remarkable magnetic properties. It strengthens neodymium magnets at high temperature and is found in wind-turbine generators and electric vehicles.","From Greek dysprositos, 'hard to get at'."],es:["Tierra rara plateada con notables propiedades magnéticas. Refuerza los imanes de neodimio a alta temperatura y está en generadores eólicos y vehículos eléctricos.","Del griego dysprositos, «difícil de conseguir»."]},
67:{el:["Αργυρό στοιχείο των σπάνιων γαιών με τη μεγαλύτερη μαγνητική ροπή από όλα τα φυσικά στοιχεία. Χρησιμοποιείται σε λέιζερ για χειρουργικές επεμβάσεις και σε υλικά ελέγχου πυρηνικών αντιδραστήρων.","Από το Holmia, το λατινικό όνομα της Στοκχόλμης."],en:["A silvery rare earth with the highest magnetic moment of any naturally occurring element. It is used in surgical lasers and in nuclear reactor control materials.","After Holmia, the Latin name of Stockholm."],es:["Tierra rara plateada con el mayor momento magnético de todos los elementos naturales. Se usa en láseres quirúrgicos y en materiales de control de reactores nucleares.","De Holmia, el nombre latino de Estocolmo."]},
68:{el:["Αργυρό στοιχείο των σπάνιων γαιών, τα ιόντα του οποίου δίνουν ροζ χρώμα σε γυαλιά και κεραμικά. Οι ίνες με πρόσμιξη ερβίου ενισχύουν τα σήματα στις οπτικές επικοινωνίες μεγάλων αποστάσεων.","Από το Ytterby, χωριό κοντά στη Στοκχόλμη."],en:["A silvery rare earth whose ions give a pink color to glass and ceramics. Erbium-doped fibers amplify signals in long-distance optical communications.","After Ytterby, the Swedish village near Stockholm."],es:["Tierra rara plateada cuyos iones dan color rosa al vidrio y la cerámica. Las fibras dopadas con erbio amplifican las señales en comunicaciones ópticas de larga distancia.","De Ytterby, la aldea sueca cercana a Estocolmo."]},
69:{el:["Ένα από τα σπανιότερα στοιχεία των σπάνιων γαιών, μαλακό και αργυρό. Χρησιμοποιείται σε φορητές πηγές ακτίνων Χ και σε ορισμένα λέιζερ στερεάς κατάστασης.","Από τη Θούλη, το αρχαίο όνομα της Σκανδιναβίας."],en:["One of the rarest of the rare earths, soft and silvery. It is used in portable X-ray sources and in some solid-state lasers.","After Thule, the ancient name for Scandinavia."],es:["Una de las tierras raras más escasas, blanda y plateada. Se usa en fuentes portátiles de rayos X y en algunos láseres de estado sólido.","De Tule, el nombre antiguo de Escandinavia."]},
70:{el:["Μαλακό, αργυρό στοιχείο των σπάνιων γαιών. Τα άτομα υττερβίου χρησιμοποιούνται σε μερικά από τα ακριβέστερα οπτικά ατομικά ρολόγια, και τα λέιζερ με πρόσμιξη υττερβίου είναι πολύ διαδεδομένα.","Από το Ytterby, χωριό κοντά στη Στοκχόλμη."],en:["A soft, silvery rare earth. Ytterbium atoms are used in some of the most precise optical atomic clocks, and ytterbium-doped lasers are widespread.","After Ytterby, the Swedish village near Stockholm."],es:["Tierra rara blanda y plateada. Los átomos de iterbio se usan en algunos de los relojes atómicos ópticos más precisos, y los láseres dopados con iterbio están muy extendidos.","De Ytterby, la aldea sueca cercana a Estocolmo."]},
71:{el:["Το σκληρότερο και πυκνότερο από τα λανθανίδια, αργυρό, σπάνιο και ακριβό μέταλλο. Κρύσταλλοι με βάση το λουτέτιο χρησιμοποιούνται στους τομογράφους PET.","Από το Lutetia, το ρωμαϊκό όνομα του Παρισιού."],en:["The hardest and densest of the lanthanides, a silvery, rare and costly metal. Lutetium-based crystals are used in PET scanners.","From Lutetia, the Roman name of Paris."],es:["El más duro y denso de los lantánidos, un metal plateado, raro y costoso. Los cristales basados en lutecio se usan en escáneres PET.","De Lutecia, el nombre romano de París."]},
72:{el:["Γυαλιστερό, όλκιμο μέταλλο χημικά παρόμοιο με το ζιρκόνιο, που απορροφά εξαιρετικά νετρόνια για ράβδους ελέγχου πυρηνικών αντιδραστήρων. Το οξείδιο του άφνιου χρησιμοποιείται σε μονωτικά των σύγχρονων μικροτσίπ.","Από το Hafnia, το λατινικό όνομα της Κοπεγχάγης, όπου ανακαλύφθηκε."],en:["A lustrous, ductile metal chemically similar to zirconium, with excellent neutron absorption for nuclear control rods. Hafnium oxide is used in insulators of modern microchips.","From Hafnia, the Latin name of Copenhagen, where it was discovered."],es:["Metal brillante y dúctil, químicamente parecido al circonio, con excelente absorción de neutrones para barras de control nuclear. El óxido de hafnio se usa en aislantes de los microchips modernos.","De Hafnia, el nombre latino de Copenhague, donde se descubrió."]},
73:{el:["Πυκνό μέταλλο, εξαιρετικά ανθεκτικό στη διάβρωση. Οι πυκνωτές ταντάλου βρίσκονται σε κινητά και φορητούς υπολογιστές, και το μέταλλο είναι ασφαλές για χειρουργικά εμφυτεύματα.","Από τον Τάνταλο της ελληνικής μυθολογίας, επειδή το μέταλλο δεν προσβάλλεται από οξέα."],en:["A dense, highly corrosion-resistant metal. Tantalum capacitors sit in phones and laptops, and the metal is safe for surgical implants.","After Tantalus of Greek myth, because the metal resists attack by acids."],es:["Metal denso y muy resistente a la corrosión. Los condensadores de tántalo están en teléfonos y portátiles, y el metal es seguro para implantes quirúrgicos.","De Tántalo, personaje de la mitología griega, porque el metal resiste el ataque de los ácidos."]},
74:{el:["Το μέταλλο με το υψηλότερο σημείο τήξης (περίπου 3.420 °C). Χρησιμοποιείται σε νήματα λαμπτήρων, κοπτικά εργαλεία και ηλεκτρόδια συγκόλλησης.","Από το σουηδικό tung sten, «βαρύς λίθος»· το σύμβολο W προέρχεται από το wolfram."],en:["The metal with the highest melting point (about 3,420 °C). It makes lamp filaments, cutting tools and welding electrodes.","From Swedish tung sten, 'heavy stone'; the symbol W comes from wolfram."],es:["El metal con el punto de fusión más alto (unos 3420 °C). Se usa en filamentos de lámparas, herramientas de corte y electrodos de soldadura.","Del sueco tung sten, «piedra pesada»; el símbolo W viene de wolfram."]},
75:{el:["Ένα από τα σπανιότερα μέταλλα στον φλοιό της Γης και από τα πυκνότερα. Τα κράματα ρηνίου κάνουν τα πτερύγια στροβίλων των κινητήρων αεριωθουμένων να αντέχουν στην ακραία θερμότητα.","Από το λατινικό Rhenus, ο ποταμός Ρήνος."],en:["One of the rarest metals in the Earth's crust and one of the densest. Rhenium alloys let jet-engine turbine blades withstand extreme heat.","From Latin Rhenus, the river Rhine."],es:["Uno de los metales más raros de la corteza terrestre y de los más densos. Las aleaciones de renio permiten que los álabes de turbina de los motores a reacción soporten calor extremo.","Del latín Rhenus, el río Rin."]},
76:{el:["Το πυκνότερο φυσικό στοιχείο, ένα γαλαζόλευκο και πολύ σκληρό μέταλλο. Χρησιμοποιείται σε κράματα για μύτες στυλό και ηλεκτρικές επαφές.","Από το ελληνικό ὀσμή, «μυρωδιά», λόγω της έντονης οσμής του πτητικού οξειδίου του."],en:["The densest naturally occurring element, a bluish-white and very hard metal. It is used in alloys for pen tips and electrical contacts.","From Greek osme, 'smell', after the pungent odor of its volatile oxide."],es:["El elemento natural más denso, un metal blanco azulado y muy duro. Se usa en aleaciones para plumas estilográficas y contactos eléctricos.","Del griego osme, «olor», por el olor penetrante de su óxido volátil."]},
77:{el:["Σκληρό, εύθραυστο μέταλλο της ομάδας του λευκόχρυσου και από τα πιο ανθεκτικά στη διάβρωση υλικά. Ένα λεπτό στρώμα ιριδίου στα πετρώματα σημαδεύει τη σύγκρουση αστεροειδούς που τερμάτισε την εποχή των δεινοσαύρων.","Από το ελληνικό ἶρις, «ουράνιο τόξο», λόγω των πολλών χρωμάτων των αλάτων του."],en:["A very hard, brittle platinum-group metal and one of the most corrosion-resistant materials. A thin layer of iridium in rock marks the asteroid impact that ended the age of the dinosaurs.","From Greek iris, 'rainbow', for the many colors of its salts."],es:["Metal muy duro y quebradizo del grupo del platino, y uno de los materiales más resistentes a la corrosión. Una fina capa de iridio en las rocas marca el impacto del asteroide que puso fin a la era de los dinosaurios.","Del griego iris, «arcoíris», por los muchos colores de sus sales."]},
78:{el:["Πυκνό, αργυρόλευκο ευγενές μέταλλο που αντιστέκεται στη διάβρωση. Είναι βασικός καταλύτης στα αυτοκίνητα και στις κυψέλες καυσίμου και χρησιμοποιείται σε κοσμήματα και σε ορισμένα αντικαρκινικά φάρμακα.","Από το ισπανικό platina, «μικρό ασήμι»."],en:["A dense, silvery-white noble metal that resists corrosion. It is a key catalyst in cars and fuel cells and is used in jewelry and some cancer drugs.","From Spanish platina, 'little silver'."],es:["Metal noble denso y blanco plateado que resiste la corrosión. Es un catalizador clave en coches y pilas de combustible y se usa en joyería y en algunos fármacos contra el cáncer.","Del español platina, «plata pequeña»."]},
79:{el:["Πυκνό, μαλακό, κίτρινο μέταλλο που δεν αμαυρώνεται, πολύτιμο ως κόσμημα και νόμισμα από την προϊστορία. Άγει καλά, γι' αυτό επικαλύπτει και ηλεκτρονικές επαφές.","Από το παλαιοαγγλικό gold· το σύμβολο Au προέρχεται από το λατινικό aurum, «χρυσός»."],en:["A dense, soft, yellow metal that never tarnishes, prized as jewelry and money since prehistory. It conducts well, so it also coats electronic contacts.","From Old English gold; the symbol Au comes from Latin aurum, 'gold'."],es:["Metal denso, blando y amarillo que no se empaña, valorado como joya y dinero desde la prehistoria. Conduce bien, por lo que también recubre contactos electrónicos.","Del inglés antiguo gold; el símbolo Au viene del latín aurum, «oro»."]},
80:{el:["Το μοναδικό μέταλλο που είναι υγρό σε συνηθισμένες θερμοκρασίες, αργυρό και πυκνό. Είναι πολύ τοξικό και οι χρήσεις του περιορίζονται σταθερά.","Από τον πλανήτη Ερμή (Mercury στα λατινικά)· το σύμβολο Hg προέρχεται από το ὑδράργυρος, «υγρό ασήμι»."],en:["The only metal that is liquid at ordinary temperatures, silvery and dense. It is highly toxic, and its uses are steadily being phased out.","After the planet Mercury; the symbol Hg comes from Greek hydrargyros, 'liquid silver'."],es:["El único metal líquido a temperaturas ordinarias, plateado y denso. Es muy tóxico y sus usos se van eliminando de forma progresiva.","Del planeta Mercurio; el símbolo Hg viene del griego hydrargyros, «plata líquida»."]},
81:{el:["Μαλακό, γκριζογάλαζο μέταλλο με εξαιρετικά δηλητηριώδεις ενώσεις. Το θάλλιο-201 χρησιμοποιείται σε ορισμένες απεικονίσεις της καρδιάς.","Από το ελληνικό θαλλός, «βλαστός», λόγω της έντονης πράσινης φασματικής γραμμής του."],en:["A soft, bluish-gray metal whose compounds are extremely poisonous. Thallium-201 is used in some heart-imaging scans.","From Greek thallos, 'green shoot', after its bright green spectral line."],es:["Metal blando y gris azulado cuyos compuestos son extremadamente venenosos. El talio-201 se usa en algunas gammagrafías del corazón.","Del griego thallos, «brote verde», por su brillante línea espectral verde."]},
82:{el:["Πολύ πυκνό, μαλακό, γκριζογάλαζο μέταλλο γνωστό από την αρχαιότητα. Είναι τοξικό, αλλά παραμένει απαραίτητο στις μπαταρίες αυτοκινήτων και ως θωράκιση από ακτινοβολία.","Από το παλαιοαγγλικό lead· το σύμβολο Pb προέρχεται από το λατινικό plumbum."],en:["A very dense, soft, bluish-gray metal known since antiquity. It is toxic, but still essential in car batteries and as radiation shielding.","From Old English lead; the symbol Pb comes from Latin plumbum."],es:["Metal muy denso, blando y gris azulado conocido desde la antigüedad. Es tóxico, pero sigue siendo esencial en las baterías de coche y como blindaje contra la radiación.","Del inglés antiguo lead; el símbolo Pb viene del latín plumbum."]},
83:{el:["Εύθραυστο, αργυρό μέταλλο με ροζ απόχρωση και ιριδίζον στρώμα οξειδίου. Οι ενώσεις του καταπραΰνουν το στομάχι, και για πολύ καιρό θεωρούνταν το βαρύτερο σταθερό στοιχείο, ώσπου ανιχνεύθηκε η εξαιρετικά αργή ραδιενεργή διάσπασή του.","Από το γερμανικό Wismut, αβέβαιης προέλευσης, που λατινοποιήθηκε ως bisemutum."],en:["A brittle, silvery metal with a pink tinge and an iridescent oxide layer. Its compounds soothe stomachs, and it was long thought to be the heaviest stable element until its extremely slow radioactive decay was detected.","From German Wismut, of uncertain origin, Latinized as bisemutum."],es:["Metal frágil y plateado con un matiz rosado y una capa de óxido iridiscente. Sus compuestos calman el estómago, y durante mucho tiempo se creyó el elemento estable más pesado hasta que se detectó su desintegración radiactiva extremadamente lenta.","Del alemán Wismut, de origen incierto, latinizado como bisemutum."]},
84:{el:["Σπάνιο, εξαιρετικά ραδιενεργό μέταλλο που ανακάλυψαν η Marie και ο Pierre Curie. Το πολώνιο-210 χρησιμεύει ως πηγή θερμότητας σε διαστημικό εξοπλισμό και σε εξουδετερωτές στατικού ηλεκτρισμού.","Από την Πολωνία, πατρίδα της Marie Curie."],en:["A rare, intensely radioactive metal discovered by Marie and Pierre Curie. Polonium-210 serves as a heat source in space equipment and in static eliminators.","After Poland, the homeland of Marie Curie."],es:["Metal raro e intensamente radiactivo descubierto por Marie y Pierre Curie. El polonio-210 sirve como fuente de calor en equipos espaciales y en eliminadores de electricidad estática.","De Polonia, patria de Marie Curie."]},
85:{el:["Το σπανιότερο φυσικό στοιχείο στον φλοιό της Γης, ραδιενεργό και τόσο ασταθές που υπάρχουν ελάχιστα άτομα κάθε στιγμή. Το αστατίνιο-211 μελετάται για στοχευμένη θεραπεία του καρκίνου.","Από το ελληνικό ἄστατος, «ασταθής»."],en:["The rarest naturally occurring element in the Earth's crust, radioactive and so unstable that only a tiny number of atoms exist at any time. Astatine-211 is studied for targeted cancer therapy.","From Greek astatos, 'unstable'."],es:["El elemento natural más raro de la corteza terrestre, radiactivo y tan inestable que en cada momento existen muy pocos átomos. El astato-211 se estudia para la terapia dirigida contra el cáncer.","Del griego astatos, «inestable»."]},
86:{el:["Πυκνό, άχρωμο, ραδιενεργό ευγενές αέριο που προκύπτει από τη διάσπαση του ουρανίου και του θορίου. Διαρρέει από το έδαφος στα κτίρια και είναι η δεύτερη αιτία καρκίνου του πνεύμονα μετά το κάπνισμα.","Από το ράδιο + -on, επειδή αρχικά λεγόταν «εκπνοή ραδίου»."],en:["A dense, colorless, radioactive noble gas produced by the decay of uranium and thorium. It seeps from the ground into buildings and is the second leading cause of lung cancer after smoking.","From radium + -on, since it was first called 'radium emanation'."],es:["Gas noble denso, incoloro y radiactivo que procede de la desintegración del uranio y el torio. Se filtra del suelo a los edificios y es la segunda causa de cáncer de pulmón después del tabaco.","De radio + -ón, pues al principio se llamó «emanación del radio»."]},
87:{el:["Εξαιρετικά σπάνιο και ραδιενεργό: το μακροβιότερο ισότοπό του έχει χρόνο ημιζωής μόλις 22 λεπτά. Ήταν το τελευταίο στοιχείο που ανακαλύφθηκε στη φύση.","Από τη Γαλλία, πατρίδα της ανακαλύπτριας Marguerite Perey."],en:["Extremely rare and radioactive: its longest-lived isotope has a half-life of only 22 minutes. It was the last element to be discovered in nature.","After France, the homeland of its discoverer Marguerite Perey."],es:["Extremadamente raro y radiactivo: su isótopo más longevo tiene una semivida de solo 22 minutos. Fue el último elemento descubierto en la naturaleza.","De Francia, patria de su descubridora Marguerite Perey."]},
88:{el:["Ραδιενεργό αλκαλικό γαιώδες μέταλλο που λάμπει αμυδρά στο σκοτάδι. Κάποτε χρησιμοποιούνταν σε φωτεινές βαφές και «θαυματουργά» φάρμακα, μέχρι που αντικαταστάθηκε από ασφαλέστερα υλικά.","Από το λατινικό radius, «ακτίνα», λόγω της έντονης ραδιενέργειάς του."],en:["A radioactive alkaline earth metal that glows faintly in the dark. It was once used in luminous paint and 'miracle' remedies until safer materials replaced it.","From Latin radius, 'ray', for its intense radioactivity."],es:["Metal alcalinotérreo radiactivo que brilla débilmente en la oscuridad. Se usó en pinturas luminosas y remedios «milagrosos» hasta que lo sustituyeron materiales más seguros.","Del latín radius, «rayo», por su intensa radiactividad."]},
89:{el:["Αργυρό ραδιενεργό μέταλλο που λάμπει γαλάζιο στο σκοτάδι από την έντονη ακτινοβολία του. Το ακτίνιο-225 αναπτύσσεται για στοχευμένη θεραπεία του καρκίνου.","Από το ελληνικό ἀκτίς, «ακτίνα»."],en:["A silvery radioactive metal that glows blue in the dark from its intense radiation. Actinium-225 is being developed for targeted cancer therapy.","From Greek aktis, 'ray'."],es:["Metal plateado radiactivo que brilla en azul en la oscuridad por su intensa radiación. El actinio-225 se desarrolla para terapia dirigida contra el cáncer.","Del griego aktis, «rayo»."]},
90:{el:["Ασθενώς ραδιενεργό, αργυρό μέταλλο, πιο άφθονο από τον κασσίτερο. Μελετάται ως πιθανό πυρηνικό καύσιμο και κάποτε έκανε τα φανάρια αερίου να λάμπουν.","Από τον Θωρ, τον σκανδιναβικό θεό της βροντής."],en:["A weakly radioactive, silvery metal, more abundant than tin. It is studied as a possible nuclear fuel and once made gas-lantern mantles glow.","After Thor, the Norse god of thunder."],es:["Metal plateado débilmente radiactivo, más abundante que el estaño. Se estudia como posible combustible nuclear y antaño hacía brillar las camisas de las lámparas de gas.","De Thor, el dios nórdico del trueno."]},
91:{el:["Σπάνιο, πυκνό, ραδιενεργό μέταλλο που εμφανίζεται στα μεταλλεύματα ουρανίου ως προϊόν διάσπασης. Δεν έχει σημαντικές εμπορικές χρήσεις και χρησιμοποιείται κυρίως στην έρευνα.","Από το ελληνικό πρῶτος + ακτίνιο: «πρόδρομος του ακτινίου», επειδή διασπάται σε αυτό."],en:["A rare, dense, radioactive metal found in uranium ores as a decay product. It has no significant commercial uses and is used mainly in research.","From Greek protos + actinium, 'before actinium', since it decays into it."],es:["Metal raro, denso y radiactivo que aparece en las menas de uranio como producto de desintegración. No tiene usos comerciales importantes y se emplea sobre todo en investigación.","Del griego protos + actinio, «antes del actinio», porque se desintegra en él."]},
92:{el:["Πυκνό, ασθενώς ραδιενεργό μέταλλο και το βαρύτερο φυσικά άφθονο στοιχείο. Το ουράνιο-235 τροφοδοτεί πυρηνικούς αντιδραστήρες, και τα ισότοπά του χρησιμεύουν στην ηλικιομέτρηση πετρωμάτων.","Από τον πλανήτη Ουρανό, που είχε ανακαλυφθεί λίγο πριν το στοιχείο."],en:["A dense, weakly radioactive metal and the heaviest naturally abundant element. Uranium-235 fuels nuclear reactors, and uranium isotopes are used to date rocks.","After the planet Uranus, discovered shortly before the element."],es:["Metal denso y débilmente radiactivo, el elemento más pesado que abunda en la naturaleza. El uranio-235 alimenta los reactores nucleares, y sus isótopos sirven para datar rocas.","Del planeta Urano, descubierto poco antes que el elemento."]},
93:{el:["Αργυρό ραδιενεργό μέταλλο, το πρώτο υπερουράνιο στοιχείο που παρήχθη ποτέ. Είναι υποπροϊόν των πυρηνικών αντιδραστήρων.","Από τον πλανήτη Ποσειδώνα, πέρα από τον Ουρανό, όπως το νεπτούνιο ακολουθεί το ουράνιο."],en:["A silvery radioactive metal, the first transuranium element ever made. It is a by-product of nuclear reactors.","After the planet Neptune, beyond Uranus, as neptunium follows uranium."],es:["Metal plateado radiactivo, el primer elemento transuránico obtenido. Es un subproducto de los reactores nucleares.","Del planeta Neptuno, más allá de Urano, como el neptunio sigue al uranio."]},
94:{el:["Πυκνό ραδιενεργό μέταλλο που παράγεται σε πυρηνικούς αντιδραστήρες. Το πλουτώνιο-239 χρησιμοποιείται σε πυρηνικά όπλα και το πλουτώνιο-238 τροφοδοτεί διαστημόπλοια όπως το Voyager και το Curiosity.","Από τον Πλούτωνα, τότε πλανήτη, πέρα από τον Ποσειδώνα."],en:["A dense radioactive metal made in nuclear reactors. Plutonium-239 is used in nuclear weapons, and plutonium-238 powers spacecraft such as Voyager and Curiosity.","After Pluto, then counted as a planet, beyond Neptune."],es:["Metal denso y radiactivo producido en reactores nucleares. El plutonio-239 se usa en armas nucleares y el plutonio-238 alimenta naves como la Voyager y el Curiosity.","De Plutón, entonces considerado planeta, más allá de Neptuno."]},
95:{el:["Αργυρό συνθετικό ραδιενεργό μέταλλο. Το αμερίκιο-241 είναι η μικρή ραδιενεργή πηγή στους περισσότερους οικιακούς ανιχνευτές καπνού.","Από την Αμερική, κατ' αναλογία με το ευρώπιο."],en:["A silvery synthetic radioactive metal. Americium-241 is the tiny radioactive source in most household smoke detectors.","After the Americas, by analogy with europium."],es:["Metal plateado, sintético y radiactivo. El americio-241 es la pequeña fuente radiactiva de la mayoría de los detectores de humo domésticos.","De las Américas, por analogía con el europio."]},
96:{el:["Σκληρό, αργυρό συνθετικό μέταλλο. Το κιούριο-244 έχει χρησιμοποιηθεί ως πηγή ισχύος και σε φασματόμετρα ακτίνων Χ σωματιδίων άλφα σε ρόβερ του Άρη.","Από τη Marie και τον Pierre Curie."],en:["A hard, silvery synthetic metal. Curium-244 has been used as a power source and in alpha-particle X-ray spectrometers on Mars rovers.","After Marie and Pierre Curie."],es:["Metal duro, plateado y sintético. El curio-244 se ha usado como fuente de energía y en espectrómetros de rayos X de partículas alfa en rovers de Marte.","De Marie y Pierre Curie."]},
97:{el:["Μαλακό, αργυρό συνθετικό μέταλλο που παράγεται σε αντιδραστήρες σε ποσότητες χιλιοστογράμμων. Χρησιμοποιείται κυρίως ως στόχος για τη δημιουργία υπερβαρέων στοιχείων, όπως το τενεσσίνιο.","Από το Μπέρκλεϊ της Καλιφόρνιας, όπου πρωτοπαρήχθη."],en:["A soft, silvery synthetic metal made in reactors in milligram amounts. It is mainly used as a target for creating superheavy elements such as tennessine.","After Berkeley, California, where it was first made."],es:["Metal blando, plateado y sintético, producido en reactores en cantidades de miligramos. Se usa sobre todo como blanco para crear elementos superpesados, como el teneso.","De Berkeley, California, donde se obtuvo por primera vez."]},
98:{el:["Συνθετικό ραδιενεργό μέταλλο, έντονη πηγή νετρονίων. Χρησιμοποιείται για την εκκίνηση πυρηνικών αντιδραστήρων και σε φορητές πηγές νετρονίων, π.χ. στην έρευνα πετρελαίου.","Από το Πανεπιστήμιο και την πολιτεία της Καλιφόρνιας."],en:["A synthetic radioactive metal and an intense neutron source. It is used to start up nuclear reactors and in portable neutron sources, for example in oil exploration.","After the University of California and the state of California."],es:["Metal radiactivo sintético y potente fuente de neutrones. Se usa para arrancar reactores nucleares y en fuentes portátiles de neutrones, por ejemplo en la exploración petrolera.","De la Universidad de California y del estado de California."]},
99:{el:["Συνθετικό ραδιενεργό μέταλλο που βρέθηκε πρώτα στα συντρίμμια της πρώτης δοκιμής βόμβας υδρογόνου το 1952. Παράγεται μόνο σε ελάχιστες ποσότητες για έρευνα.","Από τον Albert Einstein."],en:["A synthetic radioactive metal first found in the debris of the first hydrogen bomb test in 1952. It is made only in tiny amounts for research.","After Albert Einstein."],es:["Metal radiactivo sintético hallado por primera vez en los restos de la primera prueba de bomba de hidrógeno en 1952. Se produce solo en cantidades minúsculas para investigación.","De Albert Einstein."]},
100:{el:["Συνθετικό ραδιενεργό μέταλλο, που κι αυτό ανακαλύφθηκε στα συντρίμμια βόμβας υδρογόνου, και το βαρύτερο στοιχείο που μπορεί να παραχθεί με βομβαρδισμό νετρονίων σε αντιδραστήρα.","Από τον Enrico Fermi."],en:["A synthetic radioactive metal, also found in hydrogen-bomb debris, and the heaviest element that can be made by neutron bombardment in a reactor.","After Enrico Fermi."],es:["Metal radiactivo sintético, también hallado en los restos de una bomba de hidrógeno, y el elemento más pesado que puede obtenerse por bombardeo de neutrones en un reactor.","De Enrico Fermi."]},
101:{el:["Συνθετικό ραδιενεργό στοιχείο που πρωτοπαρήχθη άτομο προς άτομο βομβαρδίζοντας αϊνστάνιο. Διατίθεται μόνο σε ελάχιστες ποσότητες για έρευνα.","Από τον Dmitri Mendeleev, δημιουργό του περιοδικού πίνακα."],en:["A synthetic radioactive element first made one atom at a time by bombarding einsteinium. It is available only in tiny quantities for research.","After Dmitri Mendeleev, creator of the periodic table."],es:["Elemento radiactivo sintético obtenido por primera vez átomo a átomo bombardeando einstenio. Solo existe en cantidades minúsculas para investigación.","De Dmitri Mendeléyev, creador de la tabla periódica."]},
102:{el:["Συνθετικό ραδιενεργό στοιχείο με περίπλοκη ιστορία ανακάλυψης. Παράγεται μόνο σε ελάχιστες ποσότητες και μελετάται στην πυρηνική και χημική έρευνα.","Από τον Alfred Nobel, εφευρέτη του δυναμίτη και ιδρυτή των βραβείων Νόμπελ."],en:["A synthetic radioactive element with a complicated discovery history. It is made only in tiny amounts and studied in nuclear and chemical research.","After Alfred Nobel, inventor of dynamite and founder of the Nobel Prizes."],es:["Elemento radiactivo sintético con una historia de descubrimiento complicada. Se produce solo en cantidades minúsculas y se estudia en investigación nuclear y química.","De Alfred Nobel, inventor de la dinamita y fundador de los premios Nobel."]},
103:{el:["Το τελευταίο των ακτινιδίων, συνθετικό ραδιενεργό στοιχείο που παράγεται λίγα άτομα τη φορά. Οι ιδιότητές του μελετώνται για να κατανοηθούν τα σχετικιστικά φαινόμενα στα βαριά άτομα.","Από τον Ernest Lawrence, εφευρέτη του κυκλοτρονίου."],en:["The last of the actinides, a synthetic radioactive element made a few atoms at a time. Its properties are studied to understand relativistic effects in heavy atoms.","After Ernest Lawrence, inventor of the cyclotron."],es:["El último de los actínidos, un elemento radiactivo sintético obtenido unos pocos átomos cada vez. Se estudian sus propiedades para entender los efectos relativistas en átomos pesados.","De Ernest Lawrence, inventor del ciclotrón."]},
104:{el:["Το πρώτο υπερβαρύ στοιχείο, που παράγεται άτομο προς άτομο σε επιταχυντές σωματιδίων. Το μακροβιότερο γνωστό ισότοπό του έχει χρόνο ημιζωής περίπου μία ώρα, και η χημεία του μοιάζει με του άφνιου.","Από τον Ernest Rutherford, πρωτοπόρο της πυρηνικής φυσικής."],en:["The first superheavy element, produced atom by atom in particle accelerators. Its longest-lived known isotope has a half-life of about an hour, and its chemistry resembles that of hafnium.","After Ernest Rutherford, pioneer of nuclear physics."],es:["El primer elemento superpesado, producido átomo a átomo en aceleradores de partículas. Su isótopo más longevo conocido tiene una semivida de aproximadamente una hora, y su química se parece a la del hafnio.","De Ernest Rutherford, pionero de la física nuclear."]},
105:{el:["Συνθετικό υπερβαρύ στοιχείο που παράγεται άτομο προς άτομο σε επιταχυντές. Τα πιο σταθερά γνωστά ισότοπά του διαρκούν περίπου μία ημέρα, και συμπεριφέρεται σαν το ταντάλιο.","Από τη Ντούμπνα, ρωσική πόλη όπου εδρεύει το Ενιαίο Ινστιτούτο Πυρηνικής Έρευνας."],en:["A synthetic superheavy element made one atom at a time in accelerators. Its most stable known isotopes last about a day, and it behaves like tantalum.","After Dubna, the Russian town where the Joint Institute for Nuclear Research is based."],es:["Elemento superpesado sintético obtenido átomo a átomo en aceleradores. Sus isótopos más estables conocidos duran aproximadamente un día, y se comporta como el tántalo.","De Dubná, la ciudad rusa sede del Instituto Unificado de Investigaciones Nucleares."]},
106:{el:["Συνθετικό υπερβαρύ στοιχείο, του οποίου τα πιο σταθερά γνωστά ισότοπα διαρκούν μόνο λεπτά. Στις μελέτες μεμονωμένων ατόμων συμπεριφέρεται σαν το βολφράμιο και το μολυβδαίνιο.","Από τον Glenn T. Seaborg, που ζούσε όταν δόθηκε το όνομα."],en:["A synthetic superheavy element whose most stable known isotopes last only minutes. In studies of single atoms it behaves like tungsten and molybdenum.","After Glenn T. Seaborg, who was still alive when it was named."],es:["Elemento superpesado sintético cuyos isótopos más estables conocidos duran solo minutos. En estudios de átomos individuales se comporta como el wolframio y el molibdeno.","De Glenn T. Seaborg, que aún vivía cuando se le dio el nombre."]},
107:{el:["Συνθετικό υπερβαρύ στοιχείο που παράγεται άτομο προς άτομο. Η χημεία του, που μελετήθηκε σε λίγα άτομα, μοιάζει με του ρηνίου.","Από τον Niels Bohr, που ανέπτυξε το ατομικό μοντέλο."],en:["A synthetic superheavy element made one atom at a time. Its chemistry, studied on a handful of atoms, resembles that of rhenium.","After Niels Bohr, who developed the model of the atom."],es:["Elemento superpesado sintético obtenido átomo a átomo. Su química, estudiada con un puñado de átomos, se parece a la del renio.","De Niels Bohr, que desarrolló el modelo atómico."]},
108:{el:["Συνθετικό υπερβαρύ στοιχείο, που μελετάται για το πτητικό τετροξείδιό του, παρόμοιο με του οσμίου. Παράγεται άτομο προς άτομο.","Από το Hassia, το λατινικό όνομα της γερμανικής πολιτείας Έσση, όπου εδρεύει το εργαστήριο GSI."],en:["A synthetic superheavy element, studied through its volatile tetroxide, which resembles that of osmium. It is made atom by atom.","From Hassia, the Latin name of the German state of Hesse, home of the GSI laboratory."],es:["Elemento superpesado sintético, estudiado a través de su tetróxido volátil, parecido al del osmio. Se obtiene átomo a átomo.","De Hassia, el nombre latino del estado alemán de Hesse, sede del laboratorio GSI."]},
109:{el:["Συνθετικό υπερβαρύ στοιχείο, που παρήχθη πρώτη φορά από ένα μόνο άτομο το 1982. Ο χρόνος ημιζωής του είναι μόνο δευτερόλεπτα, οπότε σχεδόν τίποτα δεν είναι γνωστό για τη χημεία του.","Από τη Lise Meitner, τη φυσικό που βοήθησε να εξηγηθεί η πυρηνική σχάση."],en:["A synthetic superheavy element, first produced from a single atom in 1982. Its half-life is only seconds, so almost nothing is known about its chemistry.","After Lise Meitner, the physicist who helped explain nuclear fission."],es:["Elemento superpesado sintético, obtenido por primera vez a partir de un único átomo en 1982. Su semivida es de solo segundos, por lo que casi nada se sabe de su química.","De Lise Meitner, la física que ayudó a explicar la fisión nuclear."]},
110:{el:["Συνθετικό υπερβαρύ στοιχείο που παράγεται λίγα άτομα τη φορά σε επιταχυντές σωματιδίων, με χρόνο ημιζωής δευτερολέπτων. Αναμένεται να συμπεριφέρεται σαν τον λευκόχρυσο.","Από το Ντάρμσταντ, γερμανική πόλη όπου παρήχθη πρώτη φορά."],en:["A synthetic superheavy element produced a few atoms at a time in particle accelerators, with a half-life of seconds. It is expected to behave like platinum.","After Darmstadt, the German city where it was first made."],es:["Elemento superpesado sintético obtenido unos pocos átomos cada vez en aceleradores de partículas, con una semivida de segundos. Se espera que se comporte como el platino.","De Darmstadt, la ciudad alemana donde se obtuvo por primera vez."]},
111:{el:["Συνθετικό υπερβαρύ στοιχείο που αναμένεται να είναι πυκνό μέταλλο όμοιο με τον χρυσό. Παρήχθη πρώτη φορά το 1994, από ελάχιστα άτομα.","Από τον Wilhelm Röntgen, ανακαλυπτή των ακτίνων Χ."],en:["A synthetic superheavy element expected to be a dense, gold-like metal. It was first made in 1994, from only a few atoms.","After Wilhelm Röntgen, discoverer of X-rays."],es:["Elemento superpesado sintético que se espera sea un metal denso similar al oro. Se obtuvo por primera vez en 1994, con muy pocos átomos.","De Wilhelm Röntgen, descubridor de los rayos X."]},
112:{el:["Συνθετικό υπερβαρύ στοιχείο με χρόνο ημιζωής δευτερολέπτων. Μικροσκοπικά πειράματα δείχνουν ότι είναι ασυνήθιστα πτητικό για μέταλλο.","Από τον Νικόλαο Κοπέρνικο, που έβαλε τον Ήλιο στο κέντρο του πλανητικού συστήματος."],en:["A synthetic superheavy element with a half-life of seconds. Tiny experiments suggest it is unusually volatile for a metal.","After Nicolaus Copernicus, who placed the Sun at the center of the planetary system."],es:["Elemento superpesado sintético con una semivida de segundos. Experimentos con muy pocos átomos sugieren que es inusualmente volátil para un metal.","De Nicolás Copérnico, que situó el Sol en el centro del sistema planetario."]},
113:{el:["Το πρώτο στοιχείο που ανακαλύφθηκε στην Ασία, παραχθέν στο RIKEN της Ιαπωνίας. Συνθετικό υπερβαρύ στοιχείο με χρόνο ημιζωής δευτερολέπτων, προβλέπεται να συμπεριφέρεται ως μέταλλο μετά τα μεταβατικά.","Από το Nihon, το ιαπωνικό όνομα της Ιαπωνίας."],en:["The first element discovered in Asia, made at RIKEN in Japan. A synthetic superheavy element with a half-life of seconds, it is predicted to behave like a post-transition metal.","From Nihon, the Japanese name for Japan."],es:["El primer elemento descubierto en Asia, obtenido en RIKEN, en Japón. Elemento superpesado sintético con semivida de segundos, se prevé que se comporte como un metal postransicional.","De Nihon, el nombre japonés de Japón."]},
114:{el:["Συνθετικό υπερβαρύ στοιχείο, που προβλέπεται να βρίσκεται κοντά στο «νησί σταθερότητας» των μακροβιότερων πυρήνων. Ο χρόνος ημιζωής του είναι μόνο δευτερόλεπτα.","Από το Εργαστήριο Πυρηνικών Αντιδράσεων Flerov στη Ντούμπνα, που πήρε το όνομα του φυσικού Georgy Flerov."],en:["A synthetic superheavy element predicted to lie near an 'island of stability' of longer-lived nuclei. Its half-life is only seconds.","After the Flerov Laboratory of Nuclear Reactions in Dubna, named for physicist Georgy Flerov."],es:["Elemento superpesado sintético que se predice cercano a una «isla de estabilidad» de núcleos más longevos. Su semivida es de solo segundos.","Del Laboratorio Flerov de Reacciones Nucleares en Dubná, nombrado por el físico Georgy Flerov."]},
115:{el:["Συνθετικό υπερβαρύ στοιχείο που παράγεται άτομο προς άτομο και διασπάται σε κλάσμα του δευτερολέπτου. Προβλέπεται να είναι μέταλλο.","Από την περιφέρεια της Μόσχας, όπου εδρεύει το εργαστήριο της Ντούμπνα."],en:["A synthetic superheavy element made one atom at a time, decaying in a fraction of a second. It is predicted to be a metal.","After the Moscow region, home of the Dubna laboratory."],es:["Elemento superpesado sintético obtenido átomo a átomo, que se desintegra en una fracción de segundo. Se predice que es un metal.","De la región de Moscú, sede del laboratorio de Dubná."]},
116:{el:["Συνθετικό υπερβαρύ στοιχείο με εξαιρετικά σύντομο χρόνο ημιζωής χιλιοστών του δευτερολέπτου. Παρήχθη πρώτη φορά στη Ντούμπνα το 2000.","Από το Εθνικό Εργαστήριο Lawrence Livermore της Καλιφόρνιας, που συνεργάστηκε στην ανακάλυψή του."],en:["A synthetic superheavy element with an extremely short half-life of milliseconds. It was first produced in Dubna in 2000.","After the Lawrence Livermore National Laboratory in California, which collaborated in its discovery."],es:["Elemento superpesado sintético con una semivida extremadamente corta, de milisegundos. Se produjo por primera vez en Dubná en el año 2000.","Del Laboratorio Nacional Lawrence Livermore, en California, que colaboró en su descubrimiento."]},
117:{el:["Συνθετικό υπερβαρύ στοιχείο, το δεύτερο βαρύτερο που είναι γνωστό και το τελευταίο αλογόνο. Ο χρόνος ημιζωής του είναι κλάσματα του δευτερολέπτου και προβλέπεται να είναι πιο μεταλλικό από τα ελαφρύτερα αλογόνα.","Από το Τενεσί, πολιτεία των ΗΠΑ όπου βρίσκονται το Εθνικό Εργαστήριο Oak Ridge και το Πανεπιστήμιο Vanderbilt."],en:["A synthetic superheavy element, the second-heaviest known and the last halogen. Its half-life is a fraction of a second, and it is predicted to be more metallic than the lighter halogens.","After Tennessee, home of Oak Ridge National Laboratory and Vanderbilt University."],es:["Elemento superpesado sintético, el segundo más pesado conocido y el último halógeno. Su semivida es una fracción de segundo, y se predice que es más metálico que los halógenos más ligeros.","De Tennessee, sede del Laboratorio Nacional de Oak Ridge y de la Universidad Vanderbilt."]},
118:{el:["Το βαρύτερο γνωστό στοιχείο, ένα συνθετικό ευγενές αέριο με διάρκεια ζωής ατόμου κάτω από ένα χιλιοστό του δευτερολέπτου. Οι υπολογισμοί δείχνουν ότι είναι πιο δραστικό από τα ελαφρύτερα ευγενή αέρια.","Από τον Yuri Oganessian, τον πυρηνικό φυσικό που ηγήθηκε της ανακάλυψής του."],en:["The heaviest element known, a synthetic noble gas whose atoms live for under a millisecond. Calculations suggest it is more reactive than the lighter noble gases.","After Yuri Oganessian, the nuclear physicist who led its discovery."],es:["El elemento más pesado conocido, un gas noble sintético cuyos átomos viven menos de un milisegundo. Los cálculos sugieren que es más reactivo que los gases nobles más ligeros.","De Yuri Oganesián, el físico nuclear que dirigió su descubrimiento."]}
};
